			storage := LoadedStorage(t, c.Load)
			t.Cleanup(func() { storage.Close() })

			qry, err := engine.NewRangeQuery(context.Background(), storage, nil, c.Query, c.Start, c.End, c.Interval)
			require.NoError(t, err)

